/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["cpp"]=g.BC_LEI_REVISAO["cpp"]||{};g.BC_LEI_REVISAO["cpp"][22]=[{"key":"cf:5","law":"cf","ref":"5","label":"Constituição Federal — art. 5","paragraphs":["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","I - homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição;","II - ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei;","III - ninguém será submetido a tortura nem a tratamento desumano ou degradante;","IV - é livre a manifestação do pensamento, sendo vedado o anonimato;","V - é assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou à imagem;","VI - é inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias;","VII - é assegurada, nos termos da lei, a prestação de assistência religiosa nas entidades civis e militares de internação coletiva;","VIII - ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e recusar-se a cumprir prestação alternativa, fixada em lei;","IX - é livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de censura ou licença;","X - são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação;","XI - a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial;","XII - é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;","XIII - é livre o exercício de qualquer trabalho, ofício ou profissão, atendidas as qualificações profissionais que a lei estabelecer;","XIV - é assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional;","XV - é livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus bens;","XVI - todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;","XVII - é plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar;","XVIII - a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento;","XIX - as associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado;","XX - ninguém poderá ser compelido a associar-se ou a permanecer associado;","XXI - as entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados judicial ou extrajudicialmente;","XXII - é garantido o direito de propriedade;","XXIII - a propriedade atenderá a sua função social;","XXIV - a lei estabelecerá o procedimento para desapropriação por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos nesta Constituição;","XXV - no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano;","XXVI - a pequena propriedade rural, assim definida em lei, desde que trabalhada pela família, não será objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, dispondo a lei sobre os meios de financiar o seu desenvolvimento;","XXVII - aos autores pertence o direito exclusivo de utilização, publicação ou reprodução de suas obras, transmissível aos herdeiros pelo tempo que a lei fixar;","XXVIII - são assegurados, nos termos da lei:","a) a proteção às participações individuais em obras coletivas e à reprodução da imagem e voz humanas, inclusive nas atividades desportivas;","b) o direito de fiscalização do aproveitamento econômico das obras que criarem ou de que participarem aos criadores, aos intérpretes e às respectivas representações sindicais e associativas;","XXIX - a lei assegurará aos autores de inventos industriais privilégio temporário para sua utilização, bem como proteção às criações industriais, à propriedade das marcas, aos nomes de empresas e a outros signos distintivos, tendo em vista o interesse social e o desenvolvimento tecnológico e econômico do País;","XXX - é garantido o direito de herança;","XXXI - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do de cujus;","XXXII - o Estado promoverá, na forma da lei, a defesa do consumidor;","XXXIII - todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, que serão prestadas no prazo da lei, sob pena de responsabilidade, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado;","XXXIV - são a todos assegurados, independentemente do pagamento de taxas:","a) o direito de petição aos poderes públicos em defesa de direitos ou contra ilegalidade ou abuso de poder;","b) a obtenção de certidões em repartições públicas, para defesa de direitos e esclarecimento de situações de interesse pessoal;","XXXV - a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;","XXXVI - a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;","XXXVII - não haverá juízo ou tribunal de exceção;","XXXVIII - é reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados:","a) a plenitude de defesa;","b) o sigilo das votações;","c) a soberania dos veredictos;","d) a competência para o julgamento dos crimes dolosos contra a vida;","XXXIX - não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal;","XL - a lei penal não retroagirá, salvo para beneficiar o réu;","XLI - a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;","XLII - a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;","XLIII - a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem;","XLIV - constitui crime inafiançável e imprescritível a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado democrático;","XLV - nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser, nos termos da lei, estendidas aos sucessores e contra eles executadas, até o limite do valor do patrimônio transferido;","XLVI - a lei regulará a individualização da pena e adotará, entre outras, as seguintes:","a) privação ou restrição da liberdade;","b) perda de bens;","c) multa;","d) prestação social alternativa;","e) suspensão ou interdição de direitos;","XLVII - não haverá penas:","a) de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX;","b) de caráter perpétuo;","c) de trabalhos forçados;","d) de banimento;","e) cruéis;","XLVIII - a pena será cumprida em estabelecimentos distintos, de acordo com a natureza do delito, a idade e o sexo do apenado;","XLIX - é assegurado aos presos o respeito à integridade física e moral;","L - às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação;","LI - nenhum brasileiro será extraditado, salvo o naturalizado, em caso de crime comum, praticado antes da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei;","LII - não será concedida extradição de estrangeiro por crime político ou de opinião;","LIII - ninguém será processado nem sentenciado senão pela autoridade competente;","LIV - ninguém será privado da liberdade ou de seus bens sem o devido processo legal;","LV - aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e a ampla defesa, com os meios e recursos a ela inerentes;","LVI - são inadmissíveis, no processo, as provas obtidas por meios ilícitos;","LVII - ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;","LVIII - o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei;","LIX - será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal;","LX - a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem;","LXI - ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;","LXII - a prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada;","LXIII - o preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado;","LXIV - o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial;","LXV - a prisão ilegal será imediatamente relaxada pela autoridade judiciária;","LXVI - ninguém será levado à prisão ou nela mantido quando a lei admitir a liberdade provisória, com ou sem fiança;","LXVII - não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;","LXVIII - conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder;","LXIX - conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública ou agente de pessoa jurídica no exercício de atribuições do poder público;","LXX - o mandado de segurança coletivo pode ser impetrado por:","a) partido político com representação no Congresso Nacional;","b) organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados;","LXXI - conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania;","LXXII - conceder-se-á habeas data:","a) para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público;","b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo;","LXXIII - qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, salvo comprovada má-fé, isento de custas judiciais e do ônus da sucumbência;","LXXIV - o Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos;","LXXV - o Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na sentença;","LXXVI - são gratuitos para os reconhecidamente pobres, na forma da lei:","a) o registro civil de nascimento;","b) a certidão de óbito;","LXXVII - são gratuitas as ações de habeas corpus e habeas data, e, na forma da lei, os atos necessários ao exercício da cidadania.","LXXVIII - a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação. (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","LXXIX - é assegurado, nos termos da lei, o direito à proteção dos dados pessoais, inclusive nos meios digitais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","§ 1º As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.","§ 2º Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte.","§ 3º Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)","§ 4º O Brasil se submete à jurisdição de Tribunal Penal Internacional a cuja criação tenha manifestado adesão. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"cpp:647","law":"cpp","ref":"647","label":"CPP — art. 647","paragraphs":["Art. 647. Dar-se-á habeas corpus sempre que alguém sofrer ou se achar na iminência de sofrer violência ou coação ilegal na sua liberdade de ir e vir, salvo nos casos de punição disciplinar."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:648","law":"cpp","ref":"648","label":"CPP — art. 648","paragraphs":["Art. 648. A coação considerar-se-á ilegal:","I - quando não houver justa causa;","II - quando alguém estiver preso por mais tempo do que determina a lei;","III - quando quem ordenar a coação não tiver competência para fazê-lo;","IV - quando houver cessado o motivo que autorizou a coação;","V - quando não for alguém admitido a prestar fiança, nos casos em que a lei a autoriza;","VI - quando o processo for manifestamente nulo;","VII - quando extinta a punibilidade."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:649","law":"cpp","ref":"649","label":"CPP — art. 649","paragraphs":["Art. 649. O juiz ou o tribunal, dentro dos limites da sua jurisdição, fará passar imediatamente a ordem impetrada, nos casos em que tenha cabimento, seja qual for a autoridade coatora."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:650","law":"cpp","ref":"650","label":"CPP — art. 650","paragraphs":["Art. 650. Competirá conhecer, originariamente, do pedido de habeas corpus:","I - ao Supremo Tribunal Federal, nos casos previstos no art. 101, I, g, da Constituição;","II - aos Tribunais de Apelação, sempre que os atos de violência ou coação forem atribuídos a governadores, ou interventores, dos Estados ou Territórios e ao prefeito do Distrito Federal, ou a seus secretários, ou aos chefes de Polícia. (Inciso retificado no DOU de 24/10/1941)","§ 1º A competência do juiz cessará sempre que a violência ou coação provier de autoridade judiciária de igual ou superior jurisdição.","§ 2º Não cabe o habeas corpus contra a prisão administrativa, atual ou iminente, dos responsáveis por dinheiro ou valor pertencente à Fazenda Pública, alcançados ou omissos em fazer o seu recolhimento nos prazos legais, salvo se o pedido for acompanhado de prova de quitação ou de depósito do alcance verificado, ou se a prisão exceder o prazo legal."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:651","law":"cpp","ref":"651","label":"CPP — art. 651","paragraphs":["Art. 651. A concessão do habeas corpus não obstará, nem porá termo ao processo, desde que este não esteja em conflito com os fundamentos daquela."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:652","law":"cpp","ref":"652","label":"CPP — art. 652","paragraphs":["Art. 652. Se o habeas corpus for concedido em virtude de nulidade do processo, este será renovado."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:653","law":"cpp","ref":"653","label":"CPP — art. 653","paragraphs":["Art. 653. Ordenada a soltura do paciente em virtude de habeas corpus, será condenada nas custas a autoridade que, por má-fé ou evidente abuso de poder, tiver determinado a coação.","Parágrafo único. Neste caso, será remetida ao Ministério Público cópia das peças necessárias para ser promovida a responsabilidade da autoridade."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:654","law":"cpp","ref":"654","label":"CPP — art. 654","paragraphs":["Art. 654. O habeas corpus poderá ser impetrado por qualquer pessoa, em seu favor ou de outrem, bem como pelo Ministério Público.","§ 1º A petição de habeas corpus conterá:","a) o nome da pessoa que sofre ou está ameaçada de sofrer violência ou coação e o de quem exercer a violência, coação ou ameaça;","b) a declaração da espécie de constrangimento ou, em caso de simples ameaça de coação, as razões em que funda o seu temor;","c) a assinatura do impetrante, ou de alguém a seu rogo, quando não souber ou não puder escrever, e a designação das respectivas residências.","§ 2º Os juízes e os tribunais têm competência para expedir de ofício ordem de habeas corpus, quando no curso de processo verificarem que alguém sofre ou está na iminência de sofrer coação ilegal."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:655","law":"cpp","ref":"655","label":"CPP — art. 655","paragraphs":["Art. 655. O carcereiro ou o diretor da prisão, o escrivão, o oficial de justiça ou a autoridade judiciária ou policial que embaraçar ou procrastinar a expedição de ordem de habeas corpus, as informações sobre a causa da prisão, a condução e apresentação do paciente, ou a sua soltura, será multado na quantia de duzentos mil-réis a um conto de réis, sem prejuízo das penas em que incorrer.","As multas serão impostas pelo juiz do tribunal que julgar o habeas corpus, salvo quando se tratar de autoridade judiciária, caso em que caberá ao Supremo Tribunal Federal ou ao Tribunal de Apelação impor as multas."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:656","law":"cpp","ref":"656","label":"CPP — art. 656","paragraphs":["Art. 656. Recebida a petição de habeas corpus, o juiz, se julgar necessário, e estiver preso o paciente, mandará que este lhe seja imediatamente apresentado em dia e hora que designar.","Parágrafo único. Em caso de desobediência, será expedido mandado de prisão contra o detentor, que será processado na forma da lei, e o juiz providenciará para que o paciente seja tirado da prisão e apresentado em juízo."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:657","law":"cpp","ref":"657","label":"CPP — art. 657","paragraphs":["Art. 657. Se o paciente estiver preso, nenhum motivo escusará a sua apresentação, salvo:","I - grave enfermidade do paciente;","II - não estar ele sob a guarda da pessoa a quem se atribui a detenção;","III - se o comparecimento não tiver sido determinado pelo juiz ou pelo tribunal.","Parágrafo único. O juiz poderá ir ao local em que o paciente se encontrar, se este não puder ser apresentado por motivo de doença."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:658","law":"cpp","ref":"658","label":"CPP — art. 658","paragraphs":["Art. 658. O detentor declarará à ordem de quem o paciente estiver preso."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:659","law":"cpp","ref":"659","label":"CPP — art. 659","paragraphs":["Art. 659. Se o juiz ou o tribunal verificar que já cessou a violência ou coação ilegal, julgará prejudicado o pedido."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:660","law":"cpp","ref":"660","label":"CPP — art. 660","paragraphs":["Art. 660. Efetuadas as diligências, e interrogado o paciente, o juiz decidirá, fundamentadamente, dentro de vinte e quatro horas.","§ 1º Se a decisão for favorável ao paciente, será logo posto em liberdade, salvo se por outro motivo dever ser mantido na prisão.","§ 2º Se os documentos que instruírem a petição evidenciarem a ilegalidade da coação, o juiz ou o tribunal ordenará que cesse imediatamente o constrangimento.","§ 3º Se a ilegalidade decorrer do fato de não ter sido o paciente admitido a prestar fiança, o juiz arbitrará o valor desta, que poderá ser prestada perante ele, remetendo, neste caso, à autoridade os respectivos autos, para serem anexados aos do inquérito policial ou aos do processo judicial.","§ 4º Se a ordem de habeas corpus for concedida para evitar ameaça de violência ou coação ilegal, dar-se-á ao paciente salvo-conduto assinado pelo juiz.","§ 5º Será incontinenti enviada cópia da decisão à autoridade que tiver ordenado a prisão ou tiver o paciente à sua disposição, a fim de juntar-se aos autos do processo.","§ 6º Quando o paciente estiver preso em lugar que não seja o da sede do juízo ou do tribunal que conceder a ordem, o alvará de soltura será expedido pelo telégrafo, se houver, observadas as formalidades estabelecidas no art. 289, parágrafo único, in fine, ou por via postal."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:661","law":"cpp","ref":"661","label":"CPP — art. 661","paragraphs":["Art. 661. Em caso de competência originária do Tribunal de Apelação, a petição de habeas corpus será apresentada ao secretário, que a enviará imediatamente ao presidente do tribunal, ou da câmara criminal, ou da turma, que estiver reunida, ou primeiro tiver de reunir-se."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:662","law":"cpp","ref":"662","label":"CPP — art. 662","paragraphs":["Art. 662. Se a petição contiver os requisitos do art. 654, § 1º, o presidente, se necessário, requisitará da autoridade indicada como coatora informações por escrito. Faltando, porém, qualquer daqueles requisitos, o presidente mandará preenchê-lo, logo que lhe for apresentada a petição."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:663","law":"cpp","ref":"663","label":"CPP — art. 663","paragraphs":["Art. 663. As diligências do artigo anterior não serão ordenadas, se o presidente entender que o habeas corpus deva ser indeferido in limine. Nesse caso, levará a petição ao tribunal, câmara ou turma, para que delibere a respeito."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:664","law":"cpp","ref":"664","label":"CPP — art. 664","paragraphs":["Art. 664. Recebidas as informações, ou dispensadas, o habeas corpus será julgado na primeira sessão, podendo, entretanto, adiar-se o julgamento para a sessão seguinte.","Parágrafo único. A decisão será tomada por maioria de votos. Havendo empate, se o presidente não tiver tomado parte na votação, proferirá voto de desempate; no caso contrário, prevalecerá a decisão mais favorável ao paciente."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:665","law":"cpp","ref":"665","label":"CPP — art. 665","paragraphs":["Art. 665. O secretário do tribunal lavrará a ordem que, assinada pelo presidente do tribunal, câmara ou turma, será dirigida por ofício ou telegrama, ao detentor, ao carcereiro ou autoridade que exercer ou ameaçar exercer o constrangimento.","Parágrafo único. A ordem transmitida por telegrama obedecerá ao disposto no art. 289, parágrafo único, in fine."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:666","law":"cpp","ref":"666","label":"CPP — art. 666","paragraphs":["Art. 666. Os regimentos dos Tribunais de Apelação estabelecerão as normas complementares para o processo e julgamento do pedido de habeas corpus de sua competência originária."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:667","law":"cpp","ref":"667","label":"CPP — art. 667","paragraphs":["Art. 667. No processo e julgamento do habeas corpus de competência originária do Supremo Tribunal Federal, bem como nos de recurso das decisões de última ou única instância, denegatórias de habeas corpus, observar-se-á, no que lhes for aplicável, o disposto nos artigos anteriores, devendo o regimento interno do tribunal estabelecer as regras complementares."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cf:142","law":"cf","ref":"142","label":"Constituição Federal — art. 142","paragraphs":["Art. 142. As Forças Armadas, constituídas pela Marinha, pelo Exército e pela Aeronáutica, são instituições nacionais permanentes e regulares, organizadas com base na hierarquia e na disciplina, sob a autoridade suprema do Presidente da República, e destinam-se à defesa da Pátria, à garantia dos poderes constitucionais e, por iniciativa de qualquer destes, da lei e da ordem.","§ 1º Lei complementar estabelecerá as normas gerais a serem adotadas na organização, no preparo e no emprego das Forças Armadas.","§ 2º Não caberá habeas corpus em relação a punições disciplinares militares.","§ 3º Os membros das Forças Armadas são denominados militares, aplicando-se-lhes, além das que vierem a ser fixadas em lei, as seguintes disposições: (Parágrafo acrescido pela Emenda Constitucional nº 18, de 1998)","I - as patentes, com prerrogativas, direitos e deveres a elas inerentes, são conferidas pelo Presidente da República e asseguradas em plenitude aos oficiais da ativa, da reserva ou reformados, sendo-lhes privativos os títulos e postos militares e, juntamente com os demais membros, o uso dos uniformes das Forças Armadas; (Inciso acrescido pela Emenda Constitucional nº 18, de 1998)","II - o militar em atividade que tomar posse em cargo ou emprego público civil permanente, ressalvada a hipótese prevista no art. 37, inciso XVI, alínea \"c\", será transferido para a reserva, nos termos da lei; (Inciso acrescido pela Emenda Constitucional nº 18, de 1998 e com nova redação dada pela Emenda Constitucional nº 77, de 2014)","III - o militar da ativa que, de acordo com a lei, tomar posse em cargo, emprego ou função pública civil temporária, não eletiva, ainda que da administração indireta, ressalvada a hipótese prevista no art.","37, inciso XVI, alínea \"c\", ficará agregado ao respectivo quadro e somente poderá, enquanto permanecer nessa situação, ser promovido por antiguidade, contando-se-lhe o tempo de serviço apenas para aquela promoção e transferência para a reserva, sendo depois de dois anos de afastamento, contínuos ou não, transferido para a reserva, nos termos da lei; (Inciso acrescido pela Emenda Constitucional nº 18, de 1998 e com nova redação dada pela Emenda Constitucional nº 77, de 2014)","IV - ao militar são proibidas a sindicalização e a greve; (Inciso acrescido pela Emenda Constitucional nº 18, de 1998)","V - o militar, enquanto em serviço ativo, não pode estar filiado a partidos políticos; (Inciso acrescido pela Emenda Constitucional nº 18, de 1998)","VI - o oficial só perderá o posto e a patente se for julgado indigno do oficialato ou com ele incompatível, por decisão de tribunal militar de caráter permanente, em tempo de paz, ou de tribunal especial, em tempo de guerra; (Inciso acrescido pela Emenda Constitucional nº 18, de 1998)","VII - o oficial condenado na justiça comum ou militar a pena privativa de liberdade superior a dois anos, por sentença transitada em julgado, será submetido ao julgamento previsto no inciso anterior; (Inciso acrescido pela Emenda Constitucional nº 18, de 1998)","VIII - aplica-se aos militares o disposto no art. 7º, incisos VIII, XII, XVII, XVIII, XIX e XXV, e no art. 37, incisos XI, XIII, XIV e XV, bem como, na forma da lei e com prevalência da atividade militar, no art. 37, inciso XVI, alínea \"c\"; (Inciso acrescido pela Emenda Constitucional nº 18, de 1998 e com nova redação dada pela Emenda Constitucional nº 77, de 2014)","IX - (Revogado pela Emenda Constitucional nº 41, de 2003)","X - a lei disporá sobre o ingresso nas Forças Armadas, os limites de idade, a estabilidade e outras condições de transferência do militar para a inatividade, os direitos, os deveres, a remuneração, as prerrogativas e outras situações especiais dos militares, consideradas as peculiaridades de suas atividades, inclusive aquelas cumpridas por força de compromissos internacionais e de guerra. (Inciso acrescido pela Emenda Constitucional nº 18, de 1998)"],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"l12016:5","law":"l12016","ref":"5","label":"Lei 12016 — art. 5","paragraphs":["Art. 5º Não se concederá mandado de segurança quando se tratar:","I - de ato do qual caiba recurso administrativo com efeito suspensivo, independentemente de caução;","II - de decisão judicial da qual caiba recurso com efeito suspensivo;","III - de decisão judicial transitada em julgado.","Parágrafo único. (VETADO)"],"url":"https://www2.camara.leg.br/legin/fed/lei/2009/lei-12016-7-agosto-2009-590271-normaatualizada-pl.html"},{"key":"cpp:647-A","law":"cpp","ref":"647-A","label":"CPP — art. 647-A","paragraphs":["Art. 647-A. No âmbito de sua competência jurisdicional, qualquer autoridade judicial poderá expedir de ofício ordem de habeas corpus, individual ou coletivo, quando, no curso de qualquer processo judicial, verificar que, por violação ao ordenamento jurídico, alguém sofre ou se acha ameaçado de sofrer violência ou coação em sua liberdade de locomoção.","Parágrafo único. A ordem de habeas corpus poderá ser concedida de ofício pelo juiz ou pelo tribunal em processo de competência originária ou recursal, ainda que não conhecidos a ação ou o recurso em que veiculado o pedido de cessação de coação ilegal. (Artigo acrescido pela Lei nº 14.836, de 8/4/2024)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cf:108","law":"cf","ref":"108","label":"Constituição Federal — art. 108","paragraphs":["Art. 108. Compete aos Tribunais Regionais Federais:","I - processar e julgar, originariamente:","a) os juízes federais da área de sua jurisdição, incluídos os da Justiça Militar e da Justiça do Trabalho, nos crimes comuns e de responsabilidade, e os membros do Ministério Público da União, ressalvada a competência da Justiça Eleitoral;","b) as revisões criminais e as ações rescisórias de julgados seus ou dos juízes federais da região;","c) os mandados de segurança e os habeas data contra ato do próprio Tribunal ou de juiz federal;","d) os habeas corpus, quando a autoridade coatora for juiz federal;","e) os conflitos de competência entre juízes federais vinculados ao Tribunal;","II - julgar, em grau de recurso, as causas decididas pelos juízes federais e pelos juízes estaduais no exercício da competência federal da área de sua jurisdição."],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"cf:109","law":"cf","ref":"109","label":"Constituição Federal — art. 109","paragraphs":["Art. 109. Aos juízes federais compete processar e julgar:","I - as causas em que a União, entidade autárquica ou empresa pública federal forem interessadas na condição de autoras, rés, assistentes ou oponentes, exceto as de falência, as de acidentes de trabalho e as sujeitas à Justiça Eleitoral e à Justiça do Trabalho;","II - as causas entre Estado estrangeiro ou organismo internacional e Município ou pessoa domiciliada ou residente no País;","III - as causas fundadas em tratado ou contrato da União com Estado estrangeiro ou organismo internacional;","IV - os crimes políticos e as infrações penais praticadas em detrimento de bens, serviços ou interesse da União ou de suas entidades autárquicas ou empresas públicas, excluídas as contravenções e ressalvada a competência da Justiça Militar e da Justiça Eleitoral;","V - os crimes previstos em tratado ou convenção internacional, quando, iniciada a execução no País, o resultado tenha ou devesse ter ocorrido no estrangeiro, ou reciprocamente;","V-A - as causas relativas a direitos humanos a que se refere o § 5º deste artigo; (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","VI - os crimes contra a organização do trabalho e, nos casos determinados por lei, contra o sistema financeiro e a ordem econômico-financeira;","VII - os habeas corpus, em matéria criminal de sua competência ou quando o constrangimento provier de autoridade cujos atos não estejam diretamente sujeitos a outra jurisdição;","VIII - os mandados de segurança e os habeas data contra ato de autoridade federal, excetuados os casos de competência dos tribunais federais;","IX - os crimes cometidos a bordo de navios ou aeronaves, ressalvada a competência da Justiça Militar;","X - os crimes de ingresso ou permanência irregular de estrangeiro, a execução de carta rogatória, após o exequatur, e de sentença estrangeira, após a homologação, as causas referentes à nacionalidade, inclusive a respectiva opção, e à naturalização;","XI - a disputa sobre direitos indígenas.","§ 1º As causas em que a União for autora serão aforadas na seção judiciária onde tiver domicílio a outra parte.","§ 2º As causas intentadas contra a União poderão ser aforadas na seção judiciária em que for domiciliado o autor, naquela onde houver ocorrido o ato ou fato que deu origem à demanda ou onde esteja situada a coisa, ou, ainda, no Distrito Federal.","§ 3º Lei poderá autorizar que as causas de competência da Justiça Federal em que forem parte instituição de previdência social e segurado possam ser processadas e julgadas na justiça estadual quando a comarca do domicílio do segurado não for sede de vara federal. (Parágrafo com redação dada pela Emenda Constitucional nº 103, de 2019)","§ 4º Na hipótese do parágrafo anterior, o recurso cabível será sempre para o Tribunal Regional Federal na área de jurisdição do juiz de primeiro grau.","§ 5º Nas hipóteses de grave violação de direitos humanos, o Procurador-Geral da República, com a finalidade de assegurar o cumprimento de obrigações decorrentes de tratados internacionais de direitos humanos dos quais o Brasil seja parte, poderá suscitar, perante o Superior Tribunal de Justiça, em qualquer fase do inquérito ou processo, incidente de deslocamento de competência para a Justiça Federal. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"cf:105","law":"cf","ref":"105","label":"Constituição Federal — art. 105","paragraphs":["Art. 105. Compete ao Superior Tribunal de Justiça:","I - processar e julgar, originariamente:","a) nos crimes comuns, os Governadores dos Estados e do Distrito Federal, e, nestes e nos de responsabilidade, os desembargadores dos Tribunais de Justiça dos Estados e do Distrito Federal, os membros dos Tribunais de Contas dos Estados e do Distrito Federal, os dos Tribunais Regionais Federais, dos Tribunais Regionais Eleitorais e do Trabalho, os membros dos Conselhos ou Tribunais de Contas dos Municípios e os do Ministério Público da União que oficiem perante tribunais;","b) os mandados de segurança e os habeas data contra ato de Ministro de Estado, dos Comandantes da Marinha, do Exército e da Aeronáutica ou do próprio Tribunal; (Alínea com redação dada pela Emenda Constitucional nº 23, de 1999)","c) os habeas corpus, quando o coator ou paciente for qualquer das pessoas mencionadas na alínea a, ou quando o coator for tribunal sujeito à sua jurisdição, Ministro de Estado ou Comandante da Marinha, do Exército ou da Aeronáutica, ressalvada a competência da Justiça Eleitoral; (Alínea com redação dada pela Emenda Constitucional nº 23, de 1999)","d) os conflitos de competência entre quaisquer tribunais, ressalvado o disposto no art. 102, I, o, bem como entre tribunal e juízes a ele não vinculados e entre juízes vinculados a tribunais diversos;","e) as revisões criminais e as ações rescisórias de seus julgados;","f) a reclamação para a preservação de sua competência e garantia da autoridade de suas decisões;","g) os conflitos de atribuições entre autoridades administrativas e judiciárias da União, ou entre autoridades judiciárias de um Estado e administrativas de outro ou do Distrito Federal, ou entre as deste e da União;","h) o mandado de injunção, quando a elaboração da norma regulamentadora for atribuição de órgão, entidade ou autoridade federal, da administração direta ou indireta, excetuados os casos de competência do Supremo Tribunal Federal e dos órgãos da Justiça Militar, da Justiça Eleitoral, da Justiça do Trabalho e da Justiça Federal;","i) a homologação de sentenças estrangeiras e a concessão de exequatur às cartas rogatórias; (Alínea acrescida pela Emenda Constitucional nº 45, de 2004)","j) os conflitos entre entes federativos, ou entre estes e o Comitê Gestor do Imposto sobre Bens e Serviços, relacionados aos tributos previstos nos arts. 156-A e 195, V; (Alínea acrescida pela Emenda Constitucional nº 132, de 2023)","II - julgar, em recurso ordinário:","a) os habeas corpus decididos em única ou última instância pelos Tribunais Regionais Federais ou pelos tribunais dos Estados, do Distrito Federal e Territórios, quando a decisão for denegatória;","b) os mandados de segurança decididos em única instância pelos Tribunais Regionais Federais ou pelos tribunais dos Estados, do Distrito Federal e Territórios, quando denegatória a decisão;","c) as causas em que forem partes Estado estrangeiro ou organismo internacional, de um lado, e, do outro, Município ou pessoa residente ou domiciliada no País;","III - julgar, em recurso especial, as causas decididas, em única ou última instância, pelos Tribunais Regionais Federais ou pelos tribunais dos Estados, do Distrito Federal e Territórios, quando a decisão recorrida:","a) contrariar tratado ou lei federal, ou negar-lhes vigência;","b) julgar válido ato de governo local contestado em face de lei federal; (Alínea com redação dada pela Emenda Constitucional nº 45, de 2004)","c) der a lei federal interpretação divergente da que lhe haja atribuído outro tribunal.","§ 1º Funcionarão junto ao Superior Tribunal de Justiça: (Primitivo parágrafo único com redação dada pela Emenda Constitucional nº 45, de 2004, transformado em § 1º pela Emenda Constitucional nº 125, de 2022)","I - a Escola Nacional de Formação e Aperfeiçoamento de Magistrados, cabendo-lhe, dentre outras funções, regulamentar os cursos oficiais para o ingresso e promoção na carreira; (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","II - o Conselho da Justiça Federal, cabendo-lhe exercer, na forma da lei, a supervisão administrativa e orçamentária da Justiça Federal de primeiro e segundo graus, como órgão central do sistema e com poderes correicionais, cujas decisões terão caráter vinculante. (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","§ 2º No recurso especial, o recorrente deve demonstrar a relevância das questões de direito federal infraconstitucional discutidas no caso, nos termos da lei, a fim de que a admissão do recurso seja examinada pelo Tribunal, o qual somente pode dele não conhecer com base nesse motivo pela manifestação de 2/3 (dois terços) dos membros do órgão competente para o julgamento. (Parágrafo acrescido pela Emenda Constitucional nº 125, de 2022)","§ 3º Haverá a relevância de que trata o § 2º deste artigo nos seguintes casos:","I - ações penais;","II - ações de improbidade administrativa;","III - ações cujo valor da causa ultrapasse 500 (quinhentos) salários mínimos;","IV - ações que possam gerar inelegibilidade;","V - hipóteses em que o acórdão recorrido contrariar jurisprudência dominante do Superior Tribunal de Justiça;","VI - outras hipóteses previstas em lei. (Parágrafo acrescido pela Emenda Constitucional nº 125, de 2022)"],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"cf:102","law":"cf","ref":"102","label":"Constituição Federal — art. 102","paragraphs":["Art. 102. Compete ao Supremo Tribunal Federal, precipuamente, a guarda da Constituição, cabendo-lhe:","I - processar e julgar, originariamente:","a) a ação direta de inconstitucionalidade de lei ou ato normativo federal ou estadual e a ação declaratória de constitucionalidade de lei ou ato normativo federal; (Alínea com redação dada pela Emenda Constitucional nº 3, de 1993)","b) nas infrações penais comuns, o Presidente da República, o Vice-Presidente, os membros do Congresso Nacional, seus próprios Ministros e o Procurador-Geral da República;","c) nas infrações penais comuns e nos crimes de responsabilidade, os Ministros de Estado e os Comandantes da Marinha, do Exército e da Aeronáutica, ressalvado o disposto no art. 52, I, os membros dos Tribunais Superiores, os do Tribunal de Contas da União e os chefes de missão diplomática de caráter permanente; (Alínea com redação dada pela Emenda Constitucional nº 23, de 1999)","d) o habeas corpus, sendo paciente qualquer das pessoas referidas nas alíneas anteriores; o mandado de segurança e o habeas data contra atos do Presidente da República, das Mesas da Câmara dos Deputados e do Senado Federal, do Tribunal de Contas da União, do Procurador-Geral da República e do próprio Supremo Tribunal Federal;","e) o litígio entre Estado estrangeiro ou organismo internacional e a União, o Estado, o Distrito Federal ou o Território;","f) as causas e os conflitos entre a União e os Estados, a União e o Distrito Federal, ou entre uns e outros, inclusive as respectivas entidades da administração indireta;","g) a extradição solicitada por Estado estrangeiro;","h) (Revogada pela Emenda Constitucional nº 45, de 2004)","i) o habeas corpus, quando o coator for Tribunal Superior ou quando o coator ou o paciente for autoridade ou funcionário cujos atos estejam sujeitos diretamente à jurisdição do Supremo Tribunal Federal, ou se trate de crime sujeito à mesma jurisdição em uma única instância; (Alínea com redação dada pela Emenda Constitucional nº 22, de 1999)","j) a revisão criminal e a ação rescisória de seus julgados;","l) a reclamação para a preservação de sua competência e garantia da autoridade de suas decisões;","m) a execução de sentença nas causas de sua competência originária, facultada a delegação de atribuições para a prática de atos processuais;","n) a ação em que todos os membros da magistratura sejam direta ou indiretamente interessados, e aquela em que mais da metade dos membros do tribunal de origem estejam impedidos ou sejam direta ou indiretamente interessados;","o) os conflitos de competência entre o Superior Tribunal de Justiça e quaisquer tribunais, entre Tribunais Superiores, ou entre estes e qualquer outro tribunal;","p) o pedido de medida cautelar das ações diretas de inconstitucionalidade;","q) o mandado de injunção, quando a elaboração da norma regulamentadora for atribuição do Presidente da República, do Congresso Nacional, da Câmara dos Deputados, do Senado Federal, da Mesa de uma dessas Casas Legislativas, do Tribunal de Contas da União, de um dos Tribunais Superiores, ou do próprio Supremo Tribunal Federal;","r) as ações contra o Conselho Nacional de Justiça e contra o Conselho Nacional do Ministério Público. (Alínea acrescida pela Emenda Constitucional nº 45, de 2004)","II - julgar, em recurso ordinário:","a) o habeas corpus, o mandado de segurança, o habeas data e o mandado de injunção decididos em única instância pelos Tribunais Superiores, se denegatória a decisão;","b) o crime político;","III - julgar, mediante recurso extraordinário, as causas decididas em única ou última instância, quando a decisão recorrida:","a) contrariar dispositivo desta Constituição;","b) declarar a inconstitucionalidade de tratado ou lei federal;","c) julgar válida lei ou ato de governo local contestado em face desta Constituição.","d) julgar válida lei local contestada em face de lei federal. (Alínea acrescida pela Emenda Constitucional nº 45, de 2004)","§ 1º A argüição de descumprimento de preceito fundamental, decorrente desta Constituição, será apreciada pelo Supremo Tribunal Federal, na forma da lei. (Parágrafo único transformado em § 1º pela Emenda Constitucional nº 3, de 1993)","§ 2º As decisões definitivas de mérito, proferidas pelo Supremo Tribunal Federal, nas ações diretas de inconstitucionalidade e nas ações declaratórias de constitucionalidade, produzirão eficácia contra todos e efeito vinculante, relativamente aos demais órgãos do Poder Judiciário e à administração pública direta e indireta, nas esferas federal, estadual e municipal.","(Parágrafo acrescido pela Emenda Constitucional nº 3, de 1993, e com nova redação dada pela Emenda Constitucional nº 45, de 2004)","§ 3º No recurso extraordinário o recorrente deverá demonstrar a repercussão geral das questões constitucionais discutidas no caso, nos termos da lei, a fim de que o Tribunal examine a admissão do recurso, somente podendo recusá-lo pela manifestação de dois terços de seus membros. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"l8038:41-A","law":"l8038","ref":"41-A","label":"Lei 8038 — art. 41-A","paragraphs":["Art. 41-A. A decisão de Turma, no Supremo Tribunal Federal e no Superior Tribunal de Justiça, será tomada pelo voto da maioria absoluta de seus membros.","Parágrafo único. Em todos os julgamentos em matéria penal ou processual penal em órgãos colegiados, havendo empate, prevalecerá a decisão mais favorável ao indivíduo imputado, proclamando-se de imediato esse resultado, ainda que, nas hipóteses de vaga aberta a ser preenchida, de impedimento, de suspeição ou de ausência, tenha sido o julgamento tomado sem a totalidade dos integrantes do colegiado.","(Artigo acrescido pela Lei nº 9.756, de 17/12/1998, e com nova redação dada pela Lei nº 14.836, de 8/4/2024)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8038-28-maio-1990-365654-normaatualizada-pl.html"},{"key":"l8038:30","law":"l8038","ref":"30","label":"Lei 8038 — art. 30","paragraphs":["Art. 30. O recurso ordinário para o Superior Tribunal de Justiça, das decisões denegatórias de Habeas Corpus, proferidas pelos Tribunais Regionais Federais ou pelos Tribunais dos Estados e do Distrito Federal, será interposto no prazo de cinco dias, com as razões do pedido de reforma."],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8038-28-maio-1990-365654-normaatualizada-pl.html"},{"key":"l12016:6","law":"l12016","ref":"6","label":"Lei 12016 — art. 6","paragraphs":["Art. 6º A petição inicial, que deverá preencher os requisitos estabelecidos pela lei processual, será apresentada em 2 (duas) vias com os documentos que instruírem a primeira reproduzidos na segunda e indicará, além da autoridade coatora, a pessoa jurídica que esta integra, à qual se acha vinculada ou da qual exerce atribuições.","§ 1º No caso em que o documento necessário à prova do alegado se ache em repartição ou estabelecimento público ou em poder de autoridade que se recuse a fornecê-lo por certidão ou de terceiro, o juiz ordenará, preliminarmente, por ofício, a exibição desse documento em original ou em cópia autêntica e marcará, para o cumprimento da ordem, o prazo de 10 (dez) dias. O escrivão extrairá cópias do documento para juntá-las à segunda via da petição.","§ 2º Se a autoridade que tiver procedido dessa maneira for a própria coatora, a ordem far-se-á no próprio instrumento da notificação.","§ 3º Considera-se autoridade coatora aquela que tenha praticado o ato impugnado ou da qual emane a ordem para a sua prática.","§ 4º (VETADO)","§ 5º Denega-se o mandado de segurança nos casos previstos pelo art. 267 da Lei nº 5.869, de 11 de janeiro de 1973 - Código de Processo Civil.","§ 6º O pedido de mandado de segurança poderá ser renovado dentro do prazo decadencial, se a decisão denegatória não lhe houver apreciado o mérito."],"url":"https://www2.camara.leg.br/legin/fed/lei/2009/lei-12016-7-agosto-2009-590271-normaatualizada-pl.html"},{"key":"l12016:23","law":"l12016","ref":"23","label":"Lei 12016 — art. 23","paragraphs":["Art. 23. O direito de requerer mandado de segurança extinguir-se-á decorridos 120 (cento e vinte) dias, contados da ciência, pelo interessado, do ato impugnado."],"url":"https://www2.camara.leg.br/legin/fed/lei/2009/lei-12016-7-agosto-2009-590271-normaatualizada-pl.html"},{"key":"cpp:622","law":"cpp","ref":"622","label":"CPP — art. 622","paragraphs":["Art. 622. A revisão poderá ser requerida em qualquer tempo, antes da extinção da pena ou após.","Parágrafo único. Não será admissível a reiteração do pedido, salvo se fundado em novas provas."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"l12016:7","law":"l12016","ref":"7","label":"Lei 12016 — art. 7","paragraphs":["Art. 7º Ao despachar a inicial, o juiz ordenará:","I - que se notifique o coator do conteúdo da petição inicial, enviando-lhe a segunda via apresentada com as cópias dos documentos, a fim de que, no prazo de 10 (dez) dias, preste as informações;","II - que se dê ciência do feito ao órgão de representação judicial da pessoa jurídica interessada, enviando-lhe cópia da inicial sem documentos, para que, querendo, ingresse no feito;","III - que se suspenda o ato que deu motivo ao pedido, quando houver fundamento relevante e do ato impugnado puder resultar a ineficácia da medida, caso seja finalmente deferida, sendo facultado exigir do impetrante caução, fiança ou depósito, com o objetivo de assegurar o ressarcimento à pessoa jurídica.","§ 1º Da decisão do juiz de primeiro grau que conceder ou denegar a liminar caberá agravo de instrumento, observado o disposto na Lei nº 5.869, de 11 de janeiro de 1973 - Código de Processo Civil.","§ 2º Não será concedida medida liminar que tenha por objeto a compensação de créditos tributários, a entrega de mercadorias e bens provenientes do exterior, a reclassificação ou equiparação de servidores públicos e a concessão de aumento ou a extensão de vantagens ou pagamento de qualquer natureza. (Parágrafo declarado inconstitucional, em controle concentrado, pelo Supremo Tribunal Federal, pela ADI nº 4.296/2009, publicada no DOU de 28/6/2021)","§ 3º Os efeitos da medida liminar, salvo se revogada ou cassada, persistirão até a prolação da sentença.","§ 4º Deferida a medida liminar, o processo terá prioridade para julgamento.","§ 5º As vedações relacionadas com a concessão de liminares previstas neste artigo se estendem à tutela antecipada a que se referem os arts. 273 e 461 da Lei nº 5.869, de 11 janeiro de 1973 - Código de Processo Civil."],"url":"https://www2.camara.leg.br/legin/fed/lei/2009/lei-12016-7-agosto-2009-590271-normaatualizada-pl.html"},{"key":"l12016:12","law":"l12016","ref":"12","label":"Lei 12016 — art. 12","paragraphs":["Art. 12. Findo o prazo a que se refere o inciso I do caput do art. 7º desta Lei, o juiz ouvirá o representante do Ministério Público, que opinará, dentro do prazo improrrogável de 10 (dez) dias.","Parágrafo único. Com ou sem o parecer do Ministério Público, os autos serão conclusos ao juiz, para a decisão, a qual deverá ser necessariamente proferida em 30 (trinta) dias."],"url":"https://www2.camara.leg.br/legin/fed/lei/2009/lei-12016-7-agosto-2009-590271-normaatualizada-pl.html"},{"key":"l12016:14","law":"l12016","ref":"14","label":"Lei 12016 — art. 14","paragraphs":["Art. 14. Da sentença, denegando ou concedendo o mandado, cabe apelação.","§ 1º Concedida a segurança, a sentença estará sujeita obrigatoriamente ao duplo grau de jurisdição.","§ 2º Estende-se à autoridade coatora o direito de recorrer.","§ 3º A sentença que conceder o mandado de segurança pode ser executada provisoriamente, salvo nos casos em que for vedada a concessão da medida liminar.","§ 4º O pagamento de vencimentos e vantagens pecuniárias assegurados em sentença concessiva de mandado de segurança a servidor público da administração direta ou autárquica federal, estadual e municipal somente será efetuado relativamente às prestações que se vencerem a contar da data do ajuizamento da inicial."],"url":"https://www2.camara.leg.br/legin/fed/lei/2009/lei-12016-7-agosto-2009-590271-normaatualizada-pl.html"},{"key":"cpp:621","law":"cpp","ref":"621","label":"CPP — art. 621","paragraphs":["Art. 621. A revisão dos processos findos será admitida:","I - quando a sentença condenatória for contrária ao texto expresso da lei penal ou à evidência dos autos;","II - quando a sentença condenatória se fundar em depoimentos, exames ou documentos comprovadamente falsos;","III - quando, após a sentença, se descobrirem novas provas de inocência do condenado ou de circunstância que determine ou autorize diminuição especial da pena."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"l8038:31","law":"l8038","ref":"31","label":"Lei 8038 — art. 31","paragraphs":["Art. 31. Distribuído o recurso, a Secretaria, imediatamente, fará os autos com vista ao Ministério Público, pelo prazo de 2 (dois) dias.","Parágrafo único. Conclusos os autos ao relator, este submeterá o feito a julgamento independentemente de pauta."],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8038-28-maio-1990-365654-normaatualizada-pl.html"},{"key":"l8038:32","law":"l8038","ref":"32","label":"Lei 8038 — art. 32","paragraphs":["Art. 32. Será aplicado, no que couber, ao processo e julgamento do recurso, o disposto com relação ao pedido originário de Habeas Corpus."],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8038-28-maio-1990-365654-normaatualizada-pl.html"}];})(window);
